        _;
    }

    modifier onlyPayoutGroupRegistrarRole() {
        if (!hasRole(Roles.PAYOUT_GROUP_REGISTRAR_ROLE, msg.sender)) revert InvalidClaimer();
        _;
    }

    // ============ PAYOUT GROUP MANAGEMENT FUNCTIONS ============

    /**
     * @notice Create a new payout group
