        if (!_isPayoutGroupActive(payoutGroupId)) revert InactivePayoutGroup();
        if (newDestination != address(0) && _isFrozen(newDestination)) revert AddressFrozen();

        address oldDestination = payoutIdToDestination[payoutGroupId];
