    function permit(
        address owner,
        address spender,
        uint256 value,
        uint256 deadline,
        bytes memory signature
    ) external whenNotPaused isNonZeroAddress(owner) isNonZeroAddress(spender) {
        _permit(owner, spender, value, deadline, signature);
    }

